{"content":"import { test } from 'node:test';
import assert from 'node:assert/strict';
import { pad, formatBytes } from '../src/format.js';

test('pad', () => assert.equal(pad(3), '03'));

test('formatBytes formats bytes without decimal places', () => {
  assert.equal(formatBytes(0), '0 B');
  assert.equal(formatBytes(512), '512 B');
  assert.equal(formatBytes(1023), '1023 B');
});

test('formatBytes uses base 1024 and one decimal place for larger units', () => {
  assert.equal(formatBytes(1024), '1.0 KB');
  assert.equal(formatBytes(1536), '1.5 KB');
  assert.equal(formatBytes(1280), '1.3 KB');
  assert.equal(formatBytes(1024 ** 2), '1.0 MB');
  assert.equal(formatBytes(1.5 * 1024 ** 2), '1.5 MB');
  assert.equal(formatBytes(1024 ** 3), '1.0 GB');
  assert.equal(formatBytes(1.5 * 1024 ** 3), '1.5 GB');
  assert.equal(formatBytes(1024 ** 4), '1024.0 GB');
});

test('formatBytes rejects negative numbers', () => {
  for (const n of [-0.5, -1, -1024]) {
    assert.throws(() => formatBytes(n), RangeError);
  }
});
